type Answer = { attempts: number; correct: boolean };

export function firstTryRate(answers: Answer[]): number {
  const answered = answers.filter((a) => a.attempts > 0);
  if (answered.length === 0) return 0;
  const firstTry = answered.filter((a) => a.correct && a.attempts === 1);
  return Math.round((firstTry.length / answered.length) * 100);
}

firstTryRate([
  { attempts: 1, correct: true },
  { attempts: 2, correct: true },
]); // → 50
